const crypto = require('crypto');
const envelope = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const headers = $json.headers || {};
const signature = headers['x-n8n-signature'] || headers['X-N8N-Signature'];
const timestamp = headers['x-n8n-timestamp'] || headers['X-N8N-Timestamp'];
if (!envelope.event_id || typeof envelope.event_id !== 'string') throw new Error('missing event_id');
if (envelope.event_type !== 'users.ingestion.completed') throw new Error('unexpected ingestion event type');
if (envelope.status !== 'completed') throw new Error('ingestion event status must be completed');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(envelope.upload_batch_id))) throw new Error('upload_batch_id must be a UUID');
if (!envelope.occurred_at || Number.isNaN(Date.parse(envelope.occurred_at))) throw new Error('invalid occurred_at');
if (!signature || !timestamp || !/^[0-9]+$/.test(String(timestamp)) || !/^sha256=[0-9a-f]{64}$/i.test(signature)) throw new Error('signed ingestion event is required');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('ingestion signature timestamp is outside the replay window');
const secret = String($env.N8N_WEBHOOK_SECRET || '');
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is required');
const canonical = value => { if (value === null || typeof value !== 'object') return JSON.stringify(value); if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`; return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`; };
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${canonical(envelope)}`, 'utf8').digest('hex');
const received = signature.slice(7);
const expectedBytes = Buffer.from(expected, 'hex');
const receivedBytes = Buffer.from(received, 'hex');
if (expectedBytes.length !== receivedBytes.length || !crypto.timingSafeEqual(expectedBytes, receivedBytes)) throw new Error('invalid ingestion event signature');
return [{ json: { ...envelope, verified: true } }];

const event = $items('Verify Signed Ingestion Event')[0].json;
const users = $items('Fetch Users').map(item => item.json);
const products = $items('Fetch Active Products').map(item => item.json);
const candidateRows = $input.all().map(item => item.json).filter(row => row.user_uuid && row.loan_product_uuid && row.sql_candidate === true);
const candidateKeys = new Set(candidateRows.map(row => `${row.user_uuid}:${row.loan_product_uuid}`));
const known = new Set(['min_monthly_income', 'max_monthly_income', 'min_credit_score', 'max_credit_score', 'employment_status', 'min_age', 'max_age']);
const matches = candidateRows.map(row => {
  const criteria = typeof row.criteria === 'string' ? JSON.parse(row.criteria) : (row.criteria || {});
  const checks = {
    min_monthly_income: criteria.min_monthly_income == null || Number(row.monthly_income) >= Number(criteria.min_monthly_income),
    max_monthly_income: criteria.max_monthly_income == null || Number(row.monthly_income) <= Number(criteria.max_monthly_income),
    min_credit_score: criteria.min_credit_score == null || Number(row.credit_score) >= Number(criteria.min_credit_score),
    max_credit_score: criteria.max_credit_score == null || Number(row.credit_score) <= Number(criteria.max_credit_score),
    min_age: criteria.min_age == null || Number(row.age) >= Number(criteria.min_age),
    max_age: criteria.max_age == null || Number(row.age) <= Number(criteria.max_age),
    employment_status: criteria.employment_status == null || (Array.isArray(criteria.employment_status) ? criteria.employment_status.map(String).map(value => value.toLowerCase()).includes(String(row.employment_status).toLowerCase()) : String(criteria.employment_status).toLowerCase() === String(row.employment_status).toLowerCase())
  };
  const unknownCriteria = Object.fromEntries(Object.entries(criteria).filter(([key]) => !known.has(key)));
  const failed = Object.entries(checks).filter(([, passed]) => !passed).map(([key]) => key);
  const reasons = failed.map(key => `${key} failed`);
  if (Object.keys(unknownCriteria).length) reasons.push(`criteria not evaluated: ${Object.keys(unknownCriteria).join(', ')}`);
  const decision = failed.length ? 'ineligible' : (Object.keys(unknownCriteria).length ? 'may_qualify' : 'eligible');
  return { upload_batch_id: event.upload_batch_id, user_uuid: row.user_uuid, loan_product_uuid: row.loan_product_uuid, user_id: row.user_id, email: row.email, user_name: row.name, product_id: row.product_id, product_name: row.product_name, decision, evaluated_criteria: checks, unknown_criteria: unknownCriteria, reasons, is_match: true };
});
const eligible = matches.filter(row => row.decision === 'eligible').length;
const mayQualify = matches.filter(row => row.decision === 'may_qualify').length;
const unknown = matches.filter(row => row.decision === 'unknown').length;
const topK = Math.max(0, Number($env.TOP_K || 10));
const metrics = { naive: users.length * products.length, candidates: candidateKeys.size, evaluated: matches.length, stored: matches.length, eligible, may_qualify: mayQualify, unknown, ineligible: matches.length - eligible - mayQualify - unknown, top_k_highlights: Math.min(topK, eligible + mayQualify + unknown) };
if (metrics.evaluated !== metrics.candidates || metrics.stored !== metrics.evaluated || metrics.candidates > metrics.naive || metrics.top_k_highlights > eligible + mayQualify + unknown) throw new Error('matching count invariants failed');
if (!matches.length) return [{ json: { ...event, is_summary: true, metrics } }];
return matches.map(match => ({ json: { ...match, metrics } }));

const source = $items('Match Users with n8n Code');
const first = source[0]?.json || {};
const metrics = first.metrics || { naive: 0, candidates: 0, evaluated: 0, stored: 0, eligible: 0, may_qualify: 0, unknown: 0, ineligible: 0, top_k_highlights: 0 };
if (metrics.evaluated !== metrics.candidates || metrics.evaluated !== metrics.stored || metrics.candidates > metrics.naive || metrics.top_k_highlights > metrics.eligible + metrics.may_qualify + metrics.unknown) throw new Error('matching count invariant failed');
return [{ json: { event_id: `match-completed:${first.upload_batch_id}`, event_type: 'matches.completed', upload_batch_id: first.upload_batch_id, status: 'completed', metrics, presentation_limit: Math.max(0, Number($env.TOP_K || 10)), verified_ingestion: true, next_workflow: 'loan-eligibility-email-delivery' } }];
